import{t as e}from"./chunks/ThreePanel.DV1pvVaH.js";import{G as t,H as n,U as r,W as i,tt as a,z as o}from"./chunks/framework.DF4UzXOs.js";var s=JSON.parse(`{"title":"Blender","description":"Introdução ao Blender para modelagem, animação e renderização.","frontmatter":{"title":"Blender","sidebar_label":"Blender","description":"Introdução ao Blender para modelagem, animação e renderização."},"headers":[],"relativePath":"blender.md","filePath":"blender.md","lastUpdated":1788529191000}`),c=Object.assign({name:`blender.md`},{setup(s){return(s,c)=>(a(),n(`div`,null,[c[0]||=o(`h1`,{id:`basico-do-blender-parte-1`,tabindex:`-1`},[i(`Básico do Blender parte 1 `),o(`a`,{class:`header-anchor`,href:`#basico-do-blender-parte-1`,"aria-label":`Permalink to “Básico do Blender parte 1”`},`​`)],-1),c[1]||=o(`blockquote`,null,[o(`p`,null,[i(`O `),o(`strong`,null,`Blender`),i(` é a suíte aberta e gratuita mais poderosa do mundo para criação 3D: engloba modelagem poligonal, escultura digital (`),o(`em`,null,`sculpting`),i(`), simulação física, animação de personagens (`),o(`em`,null,`rigging`),i(`), edição de vídeo e renderização fotorrealista (motores Eevee e Cycles).`)])],-1),t(e,{topic:`modelagem`,title:`Modelagem Poligonal no Blender`,subtitle:`Vértices, arestas e faces estruturando uma malha tridimensional no Viewport 3D.`}),c[2]||=o(`p`,null,`Aqui será abordado em maior parte a interface do Blender, serão mencionadas coisas óbvias (tipo como salvar) e coisas que na primeira leitura pode ser meio vago.`,-1),t(e,{topic:`render`,title:`Motores de Renderização (Cycles / Eevee)`,subtitle:`Sombreamento, luz e câmera gerando o quadro final a partir da cena.`}),c[3]||=r(`<h1 id="topbar-do-blender" tabindex="-1">Topbar do Blender <a class="header-anchor" href="#topbar-do-blender" aria-label="Permalink to “Topbar do Blender”">​</a></h1><p>A <strong>Topbar</strong> é a barra superior do Blender. Ela reúne os principais menus de gerenciamento do programa, arquivos, renderização, janelas e ajuda. É o equivalente à barra de menus de programas como Word, Photoshop ou Visual Studio.</p><h1 id="blender-menu" tabindex="-1">Blender Menu <a class="header-anchor" href="#blender-menu" aria-label="Permalink to “Blender Menu”">​</a></h1><p>Este menu contém informações gerais sobre o Blender e alguns atalhos importantes.</p><h2 id="tela-de-abertura" tabindex="-1">Tela de Abertura <a class="header-anchor" href="#tela-de-abertura" aria-label="Permalink to “Tela de Abertura”">​</a></h2><p>Abre novamente a tela inicial exibida quando o Blender é iniciado.</p><h2 id="sobre-o-blender" tabindex="-1">Sobre o Blender <a class="header-anchor" href="#sobre-o-blender" aria-label="Permalink to “Sobre o Blender”">​</a></h2><p>Mostra informações técnicas da instalação:</p><ul><li><strong>Version:</strong> versão instalada.</li><li><strong>Date:</strong> data de compilação.</li><li><strong>Hash:</strong> identificação única da versão (útil para suporte técnico).</li><li><strong>Branch:</strong> ramo do código-fonte utilizado.</li><li><strong>Windowing Environment:</strong> sistema gráfico utilizado no Linux (Wayland ou X11).</li></ul><h2 id="instalar-template-de-aplicacao" tabindex="-1">Instalar Template de Aplicação <a class="header-anchor" href="#instalar-template-de-aplicacao" aria-label="Permalink to “Instalar Template de Aplicação”">​</a></h2><p>Permite instalar modelos de trabalho personalizados.</p><h3 id="o-que-e-um-template" tabindex="-1">O que é um Template? <a class="header-anchor" href="#o-que-e-um-template" aria-label="Permalink to “O que é um Template?”">​</a></h3><p>Um Template altera completamente a configuração inicial do Blender. <strong>Exemplos:</strong></p><ul><li>Template para modelagem arquitetônica.</li><li>Template para animação.</li><li>Template para design industrial. Quando você cria um novo arquivo usando esse template, várias configurações já vêm prontas.</li></ul><h1 id="menu-file-arquivo" tabindex="-1">Menu File (Arquivo) <a class="header-anchor" href="#menu-file-arquivo" aria-label="Permalink to “Menu File (Arquivo)”">​</a></h1><p>É um dos menus mais importantes do Blender. Responsável por:</p><ul><li>Criar projetos</li><li>Abrir arquivos</li><li>Salvar</li><li>Importar</li><li>Exportar</li><li>Recuperar trabalhos perdidos</li></ul><h2 id="new-ctrl-n-cria-um-novo-projeto" tabindex="-1">New (Ctrl + N)Cria um novo projeto. <a class="header-anchor" href="#new-ctrl-n-cria-um-novo-projeto" aria-label="Permalink to “New (Ctrl + N)Cria um novo projeto.”">​</a></h2><p>Ao criar um novo arquivo, o Blender limpa a cena atual e carrega um modelo padrão. <strong>Exemplos:</strong></p><ul><li>General</li><li>2D Animation</li><li>Sculpting</li><li>VFX</li><li>Video Editing</li></ul><h2 id="open-ctrl-o" tabindex="-1">Open (Ctrl + O) <a class="header-anchor" href="#open-ctrl-o" aria-label="Permalink to “Open (Ctrl + O)”">​</a></h2><p>Abre um arquivo <code>.blend</code>.</p><h3 id="open-recent" tabindex="-1">Open Recent <a class="header-anchor" href="#open-recent" aria-label="Permalink to “Open Recent”">​</a></h3><p>Mostra os arquivos abertos recentemente. <strong>Detalhe importante</strong> Ao passar o mouse sobre um arquivo, o Blender exibe:</p><ul><li>Miniatura do projeto</li><li>Informações do arquivo</li><li>Caminho onde ele está salvo Isso ajuda a identificar rapidamente qual projeto deseja abrir.</li></ul><h2 id="revert" tabindex="-1">Revert <a class="header-anchor" href="#revert" aria-label="Permalink to “Revert”">​</a></h2><p>Recarrega a última versão salva.</p><h3 id="exemplo" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo" aria-label="Permalink to “Exemplo”">​</a></h3><p>Você:</p><ul><li>Salvou um projeto.</li><li>Moveu objetos.</li><li>Apagou materiais.</li><li>Cometeu vários erros.</li><li>Usando <strong>Revert</strong>, o Blender volta exatamente para o estado do último salvamento.</li></ul><h2 id="recover-recuperacao" tabindex="-1">Recover (Recuperação) <a class="header-anchor" href="#recover-recuperacao" aria-label="Permalink to “Recover (Recuperação)”">​</a></h2><p>Uma das funções mais importantes para evitar perda de trabalho.</p><h3 id="last-session" tabindex="-1">Last Session <a class="header-anchor" href="#last-session" aria-label="Permalink to “Last Session”">​</a></h3><p>Recupera o projeto da última sessão. Útil quando o Blender foi fechado sem querer.</p><h3 id="auto-save" tabindex="-1">Auto Save <a class="header-anchor" href="#auto-save" aria-label="Permalink to “Auto Save”">​</a></h3><p>Recupera arquivos de salvamento automático. O Blender cria cópias temporárias periodicamente. Se houver uma queda de energia ou travamento, você pode restaurar boa parte do trabalho.</p><h1 id="salvar-arquivos" tabindex="-1">Salvar Arquivos <a class="header-anchor" href="#salvar-arquivos" aria-label="Permalink to “Salvar Arquivos”">​</a></h1><h2 id="save-ctrl-s" tabindex="-1">Save (Ctrl + S) <a class="header-anchor" href="#save-ctrl-s" aria-label="Permalink to “Save (Ctrl + S)”">​</a></h2><p>Salva o projeto atual.</p><h2 id="save-as-shift-ctrl-s" tabindex="-1">Save As (Shift + Ctrl + S) <a class="header-anchor" href="#save-as-shift-ctrl-s" aria-label="Permalink to “Save As (Shift + Ctrl + S)”">​</a></h2><p>Salva com outro nome ou em outra pasta.</p><h2 id="save-copy" tabindex="-1">Save Copy <a class="header-anchor" href="#save-copy" aria-label="Permalink to “Save Copy”">​</a></h2><p>Cria uma cópia sem alterar o arquivo atualmente aberto.</p><h3 id="exemplo-1" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-1" aria-label="Permalink to “Exemplo”">​</a></h3><p>Você trabalha em:<code>Casa.blend</code></p><p>Usa Save Copy:<code>Casa_Backup.blend</code></p><p>Mas continua editando o arquivo original.</p><h2 id="save-incremental-ctrl-alt-s" tabindex="-1">Save Incremental (Ctrl + Alt + S) <a class="header-anchor" href="#save-incremental-ctrl-alt-s" aria-label="Permalink to “Save Incremental (Ctrl + Alt + S)”">​</a></h2><p>Uma função extremamente útil para projetos grandes. Cria automaticamente versões numeradas.</p><h3 id="exemplo-2" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-2" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Projeto_01.blend </span></span>
<span class="line"><span>Projeto_02.blend</span></span>
<span class="line"><span>Projeto_03.blend</span></span></code></pre></div><p>Isso permite voltar para versões anteriores caso algo dê errado.</p><h1 id="link-e-append" tabindex="-1">Link e Append <a class="header-anchor" href="#link-e-append" aria-label="Permalink to “Link e Append”">​</a></h1><p>Essas duas opções são muito úteis se você usa vários arquivos, além de serem algo um pouco complexo de entender no início.</p><h2 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to “Link”">​</a></h2><p>Importa dados de outro arquivo mantendo uma conexão com ele.</p><h3 id="como-funciona" tabindex="-1">Como funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to “Como funciona”">​</a></h3><p>Imagine:<code>Personagem.blend</code>contendo um personagem completo.</p><p>Você usa Link em:<code>Cena.blend</code></p><p>E o personagem aparece na cena. Mas:</p><ul><li>Não pode ser editado diretamente.</li><li>Continua pertencendo ao arquivo original. Se o arquivo original for atualizado, a cena também será atualizada.</li></ul><h2 id="append" tabindex="-1">Append <a class="header-anchor" href="#append" aria-label="Permalink to “Append”">​</a></h2><p>Também importa dados de outro arquivo. Mas cria uma cópia independente.</p><h3 id="diferenca-do-append" tabindex="-1">Diferença do append <a class="header-anchor" href="#diferenca-do-append" aria-label="Permalink to “Diferença do append”">​</a></h3><p>Após usar Append:</p><ul><li>O objeto pertence ao arquivo atual.</li><li>Pode ser editado livremente.</li><li>Não depende mais do arquivo original.</li></ul><h1 id="import-e-export" tabindex="-1">Import e Export <a class="header-anchor" href="#import-e-export" aria-label="Permalink to “Import e Export”">​</a></h1><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to “Import”">​</a></h2><p>Permite trazer modelos de outros programas.</p><h3 id="formatos-comuns" tabindex="-1">Formatos comuns <a class="header-anchor" href="#formatos-comuns" aria-label="Permalink to “Formatos comuns”">​</a></h3><ul><li>FBX</li><li>OBJ</li><li>STL</li><li>Alembic</li><li>glTF</li></ul><h3 id="exemplo-3" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-3" aria-label="Permalink to “Exemplo”">​</a></h3><p>Importar um modelo criado no AutoCAD ou Maya.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to “Export”">​</a></h2><p>Faz o contrário.Transforma projetos Blender em formatos utilizados por outros softwares ou engines.</p><h3 id="exemplo-4" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-4" aria-label="Permalink to “Exemplo”">​</a></h3><p>Exportar para:</p><ul><li>Unity</li><li>Unreal Engine</li><li>Impressão 3D</li><li>Outros programas 3D</li></ul><h1 id="external-data" tabindex="-1">External Data <a class="header-anchor" href="#external-data" aria-label="Permalink to “External Data”">​</a></h1><p>Uma das áreas mais confusas para iniciantes. Ela controla arquivos externos usados pelo projeto.</p><h3 id="exemplos" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Texturas</li><li>Imagens</li><li>HDRIs</li><li>Sons</li><li>Bibliotecas</li></ul><h2 id="pack-resources" tabindex="-1">Pack Resources <a class="header-anchor" href="#pack-resources" aria-label="Permalink to “Pack Resources”">​</a></h2><p>&quot;Empacotar recursos&quot;. O Blender coloca todos os arquivos externos dentro do próprio <code>.blend</code>.</p><h3 id="vantagem" tabindex="-1">Vantagem <a class="header-anchor" href="#vantagem" aria-label="Permalink to “Vantagem”">​</a></h3><p>Você pode mover o arquivo para outro computador sem perder texturas.</p><h2 id="unpack-resources" tabindex="-1">Unpack Resources <a class="header-anchor" href="#unpack-resources" aria-label="Permalink to “Unpack Resources”">​</a></h2><p>Faz o processo inverso. Extrai novamente os recursos para arquivos externos.</p><h2 id="automatically-pack-resources" tabindex="-1">Automatically Pack Resources <a class="header-anchor" href="#automatically-pack-resources" aria-label="Permalink to “Automatically Pack Resources”">​</a></h2><p>Todo arquivo novo usado pelo projeto será automaticamente incorporado ao <code>.blend</code>. Muito útil para evitar erros de textura perdida.</p><h1 id="caminhos-relativos-e-absolutos" tabindex="-1">Caminhos Relativos e Absolutos <a class="header-anchor" href="#caminhos-relativos-e-absolutos" aria-label="Permalink to “Caminhos Relativos e Absolutos”">​</a></h1><h2 id="make-paths-relative" tabindex="-1">Make Paths Relative <a class="header-anchor" href="#make-paths-relative" aria-label="Permalink to “Make Paths Relative”">​</a></h2><p>Transforma caminhos em relativos.</p><h3 id="exemplo-5" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-5" aria-label="Permalink to “Exemplo”">​</a></h3><p><code>Texturas\\Madeira.jpg</code> Funciona bem quando o projeto inteiro é movido para outro computador.</p><h2 id="make-paths-absolute" tabindex="-1">Make Paths Absolute <a class="header-anchor" href="#make-paths-absolute" aria-label="Permalink to “Make Paths Absolute”">​</a></h2><p>Transforma em caminho completo.</p><h3 id="exemplo-6" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-6" aria-label="Permalink to “Exemplo”">​</a></h3><p><code>C:\\Projetos\\Casa\\Texturas\\Madeira.jpg</code> Mais preciso, porém menos portátil.</p><h2 id="report-missing-files" tabindex="-1">Report Missing Files <a class="header-anchor" href="#report-missing-files" aria-label="Permalink to “Report Missing Files”">​</a></h2><p>Verifica se existem arquivos faltando.</p><h3 id="exemplo-7" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-7" aria-label="Permalink to “Exemplo”">​</a></h3><p>Você apagou uma textura sem perceber. O Blender procura referências quebradas e avisa.</p><h2 id="find-missing-files" tabindex="-1">Find Missing Files <a class="header-anchor" href="#find-missing-files" aria-label="Permalink to “Find Missing Files”">​</a></h2><p>Procura automaticamente os arquivos perdidos.</p><h3 id="exemplo-8" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-8" aria-label="Permalink to “Exemplo”">​</a></h3><p>Você moveu uma pasta de texturas. Em vez de relinkar tudo manualmente, o Blender procura os arquivos e reconecta as referências. Essa função economiza muito tempo em projetos grandes.</p><h1 id="clean-up" tabindex="-1">Clean Up <a class="header-anchor" href="#clean-up" aria-label="Permalink to “Clean Up”">​</a></h1><p>Ferramentas para limpeza do projeto.</p><h2 id="purge-unused-data" tabindex="-1">Purge Unused Data <a class="header-anchor" href="#purge-unused-data" aria-label="Permalink to “Purge Unused Data”">​</a></h2><p>Remove dados que não estão sendo utilizados.</p><h3 id="exemplos-1" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-1" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Materiais órfãos</li><li>Malhas não usadas</li><li>Imagens sem referência</li></ul><h3 id="observacao" tabindex="-1">Observação <a class="header-anchor" href="#observacao" aria-label="Permalink to “Observação”">​</a></h3><p>Não pode ser desfeito.</p><h2 id="manage-unused-data" tabindex="-1">Manage Unused Data <a class="header-anchor" href="#manage-unused-data" aria-label="Permalink to “Manage Unused Data”">​</a></h2><p>Mostra todos os dados não utilizados antes da remoção. É uma forma mais segura de analisar o projeto.</p><h1 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to “Defaults”">​</a></h1><p>Gerencia as configurações padrão do Blender.</p><h2 id="save-startup-file" tabindex="-1">Save Startup File <a class="header-anchor" href="#save-startup-file" aria-label="Permalink to “Save Startup File”">​</a></h2><p>Salva o estado atual como padrão.</p><h3 id="exemplo-9" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-9" aria-label="Permalink to “Exemplo”">​</a></h3><p>Você sempre usa:</p><ul><li>Layout específico</li><li>Luz personalizada</li><li>Coleções organizadas Pode salvar tudo isso para aparecer sempre ao abrir novos projetos.</li></ul><h2 id="load-factory-settings" tabindex="-1">Load Factory Settings <a class="header-anchor" href="#load-factory-settings" aria-label="Permalink to “Load Factory Settings”">​</a></h2><p>Restaura as configurações originais de fábrica. Útil quando algo foi configurado incorretamente.</p><h1 id="menu-edit" tabindex="-1">Menu Edit <a class="header-anchor" href="#menu-edit" aria-label="Permalink to “Menu Edit”">​</a></h1><p>Ferramentas gerais de edição.</p><h2 id="undo-redo" tabindex="-1">Undo / Redo <a class="header-anchor" href="#undo-redo" aria-label="Permalink to “Undo / Redo”">​</a></h2><ul><li>Undo = desfazer.</li><li>Redo = refazer.</li></ul><h2 id="menu-search" tabindex="-1">Menu Search <a class="header-anchor" href="#menu-search" aria-label="Permalink to “Menu Search”">​</a></h2><p>Pesquisa menus pelo nome.</p><h3 id="exemplo-10" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-10" aria-label="Permalink to “Exemplo”">​</a></h3><p>Digite:<code>Subdivision</code> e o Blender mostra onde encontrar essa função.</p><h2 id="operator-search" tabindex="-1">Operator Search <a class="header-anchor" href="#operator-search" aria-label="Permalink to “Operator Search”">​</a></h2><p>Pesquisa qualquer operação do Blender. É como uma barra de comandos. Muito útil para usuários avançados.</p><h2 id="batch-rename" tabindex="-1">Batch Rename <a class="header-anchor" href="#batch-rename" aria-label="Permalink to “Batch Rename”">​</a></h2><p>Permite renomear vários objetos simultaneamente.</p><h3 id="exemplo-11" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-11" aria-label="Permalink to “Exemplo”">​</a></h3><p>Antes:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Cube </span></span>
<span class="line"><span>Cube.001 </span></span>
<span class="line"><span>Cube.002 </span></span>
<span class="line"><span>Cube.003</span></span></code></pre></div><p>Depois:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pilar_01</span></span>
<span class="line"><span>Pilar_02</span></span>
<span class="line"><span>Pilar_03</span></span>
<span class="line"><span>Pilar_04</span></span></code></pre></div><h2 id="lock-object-modes" tabindex="-1">Lock Object Modes <a class="header-anchor" href="#lock-object-modes" aria-label="Permalink to “Lock Object Modes”">​</a></h2><p>Evita trocas acidentais de modo.</p><h3 id="exemplo-12" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-12" aria-label="Permalink to “Exemplo”">​</a></h3><p>Você está animando um esqueleto em Pose Mode. Sem querer clica em outro objeto. Normalmente o Blender sairia do modo atual. Com essa opção ativada isso não acontece.</p><h1 id="menu-render" tabindex="-1">Menu Render <a class="header-anchor" href="#menu-render" aria-label="Permalink to “Menu Render”">​</a></h1><p>Controla a renderização.</p><h2 id="render-image-f12" tabindex="-1">Render Image (F12) <a class="header-anchor" href="#render-image-f12" aria-label="Permalink to “Render Image (F12)”">​</a></h2><p>Renderiza apenas o quadro atual.</p><h2 id="render-animation-ctrl-f12" tabindex="-1">Render Animation (Ctrl + F12) <a class="header-anchor" href="#render-animation-ctrl-f12" aria-label="Permalink to “Render Animation (Ctrl + F12)”">​</a></h2><p>Renderiza todos os quadros da animação.</p><h2 id="render-audio" tabindex="-1">Render Audio <a class="header-anchor" href="#render-audio" aria-label="Permalink to “Render Audio”">​</a></h2><p>Exporta apenas o áudio da cena. Muito usado em animações e edição de vídeo.</p><h2 id="view-render-f11" tabindex="-1">View Render (F11) <a class="header-anchor" href="#view-render-f11" aria-label="Permalink to “View Render (F11)”">​</a></h2><p>Abre o último render realizado.</p><h2 id="view-animation-ctrl-f11" tabindex="-1">View Animation (Ctrl + F11) <a class="header-anchor" href="#view-animation-ctrl-f11" aria-label="Permalink to “View Animation (Ctrl + F11)”">​</a></h2><p>Reproduz a animação renderizada em um player externo.</p><h2 id="lock-interface" tabindex="-1">Lock Interface <a class="header-anchor" href="#lock-interface" aria-label="Permalink to “Lock Interface”">​</a></h2><p>Durante renderizações pesadas, bloqueia a interface para liberar mais memória para o renderizador.Em projetos grandes pode melhorar a estabilidade.</p><h1 id="menu-window" tabindex="-1">Menu Window <a class="header-anchor" href="#menu-window" aria-label="Permalink to “Menu Window”">​</a></h1><p>Gerencia janelas e áreas de trabalho.</p><h2 id="new-window" tabindex="-1">New Window <a class="header-anchor" href="#new-window" aria-label="Permalink to “New Window”">​</a></h2><p>Cria uma nova janela com o mesmo conteúdo da atual.</p><h2 id="new-main-window" tabindex="-1">New Main Window <a class="header-anchor" href="#new-main-window" aria-label="Permalink to “New Main Window”">​</a></h2><p>Cria uma janela independente. Ela pode mostrar:</p><ul><li>Outra cena</li><li>Outro workspace</li><li>Outro contexto Muito útil em monitores múltiplos.</li></ul><h2 id="toggle-window-fullscreen" tabindex="-1">Toggle Window Fullscreen <a class="header-anchor" href="#toggle-window-fullscreen" aria-label="Permalink to “Toggle Window Fullscreen”">​</a></h2><p>Alterna para tela cheia.</p><h2 id="next-workspace-previous-workspace" tabindex="-1">Next Workspace / Previous Workspace <a class="header-anchor" href="#next-workspace-previous-workspace" aria-label="Permalink to “Next Workspace / Previous Workspace”">​</a></h2><p>Navega rapidamente entre os workspaces.</p><h2 id="show-status-bar" tabindex="-1">Show Status Bar <a class="header-anchor" href="#show-status-bar" aria-label="Permalink to “Show Status Bar”">​</a></h2><p>Mostra ou oculta a barra inferior de informações.</p><h2 id="save-screenshot" tabindex="-1">Save Screenshot <a class="header-anchor" href="#save-screenshot" aria-label="Permalink to “Save Screenshot”">​</a></h2><p>Captura toda a janela do Blender.</p><h2 id="save-screenshot-editor" tabindex="-1">Save Screenshot (Editor) <a class="header-anchor" href="#save-screenshot-editor" aria-label="Permalink to “Save Screenshot (Editor)”">​</a></h2><p>Captura apenas um editor específico.</p><h3 id="exemplo-13" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-13" aria-label="Permalink to “Exemplo”">​</a></h3><ul><li>Apenas o Viewport.</li><li>Apenas o Shader Editor.</li><li>Apenas o UV Editor.</li></ul><h1 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to “Workspaces”">​</a></h1><p>Os Workspaces são conjuntos de janelas organizadas para tarefas específicas.</p><h3 id="exemplos-2" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-2" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Layout</li><li>Modeling</li><li>Sculpting</li><li>UV Editing</li><li>Shading</li><li>Animation</li><li>Rendering</li><li>Compositing</li><li>Cada Workspace reorganiza automaticamente os editores para facilitar aquela atividade.</li></ul><h1 id="scenes-view-layers" tabindex="-1">Scenes &amp; View Layers <a class="header-anchor" href="#scenes-view-layers" aria-label="Permalink to “Scenes &amp; View Layers”">​</a></h1><p>Localizados no canto superior direito.</p><h2 id="scene" tabindex="-1">Scene <a class="header-anchor" href="#scene" aria-label="Permalink to “Scene”">​</a></h2><p>Permite alternar entre diferentes cenas dentro do mesmo arquivo.</p><h3 id="exemplo-14" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-14" aria-label="Permalink to “Exemplo”">​</a></h3><ul><li>Cena da casa.</li><li>Cena da garagem.</li><li>Cena do jardim.</li><li>Tudo dentro de um único <code>.blend</code>.</li></ul><h2 id="view-layer" tabindex="-1">View Layer <a class="header-anchor" href="#view-layer" aria-label="Permalink to “View Layer”">​</a></h2><p>Controla quais objetos serão exibidos e renderizados.</p><h3 id="exemplo-pratico" tabindex="-1">Exemplo prático <a class="header-anchor" href="#exemplo-pratico" aria-label="Permalink to “Exemplo prático”">​</a></h3><p>Você pode ter:</p><ul><li>Layer para render final.</li><li>Layer para testes.</li><li>Layer apenas para sombras.</li><li>Layer apenas para efeitos especiais. Isso é extremamente importante em projetos profissionais de animação e VFX.</li></ul><h1 id="status-bar" tabindex="-1">Status Bar <a class="header-anchor" href="#status-bar" aria-label="Permalink to “Status Bar”">​</a></h1><p>A <strong>Status Bar (Barra de Status)</strong> é a barra localizada na parte inferior da janela do Blender. Sua função é fornecer informações rápidas e contextuais sobre o que está acontecendo no programa, incluindo atalhos, mensagens do sistema, progresso de tarefas e estatísticas da cena.</p><p>Ela ajuda o usuário a acompanhar o estado atual do projeto sem precisar abrir menus adicionais.</p><hr><h1 id="localizacao-e-visibilidade" tabindex="-1">Localização e Visibilidade <a class="header-anchor" href="#localizacao-e-visibilidade" aria-label="Permalink to “Localização e Visibilidade”">​</a></h1><p>A Status Bar fica na parte inferior da interface principal do Blender.</p><p>Ela pode ser ocultada de duas maneiras:</p><ul><li>Desativando <strong>Show Status Bar</strong> no menu <strong>Window</strong>.</li><li>Arrastando sua borda superior para baixo até escondê-la.</li></ul><p>Essa opção pode ser útil para aumentar a área de trabalho em monitores menores.</p><hr><h1 id="estrutura-da-status-bar" tabindex="-1">Estrutura da Status Bar <a class="header-anchor" href="#estrutura-da-status-bar" aria-label="Permalink to “Estrutura da Status Bar”">​</a></h1><p>A barra é dividida em três regiões principais:</p><h2 id="lado-esquerdo" tabindex="-1">Lado Esquerdo <a class="header-anchor" href="#lado-esquerdo" aria-label="Permalink to “Lado Esquerdo”">​</a></h2><p>Exibe:</p><ul><li>Atalhos de mouse.</li><li>Atalhos do teclado.</li><li>Informações da ferramenta ativa.</li></ul><h2 id="centro" tabindex="-1">Centro <a class="header-anchor" href="#centro" aria-label="Permalink to “Centro”">​</a></h2><p>Exibe:</p><ul><li>Mensagens informativas.</li><li>Avisos.</li><li>Progresso de tarefas em execução.</li></ul><h2 id="lado-direito" tabindex="-1">Lado Direito <a class="header-anchor" href="#lado-direito" aria-label="Permalink to “Lado Direito”">​</a></h2><p>Exibe:</p><ul><li>Estatísticas da cena.</li><li>Informações de memória.</li><li>Duração da animação.</li><li>Atualizações de extensões.</li><li>Versão do Blender.</li></ul><hr><h1 id="_1-informacoes-de-atalhos" tabindex="-1">1. Informações de Atalhos <a class="header-anchor" href="#_1-informacoes-de-atalhos" aria-label="Permalink to “1. Informações de Atalhos”">​</a></h1><p>O lado esquerdo da Status Bar apresenta informações relacionadas à ferramenta atualmente selecionada.</p><p>Essas informações incluem:</p><ul><li>Botões do mouse utilizados.</li><li>Teclas de atalho.</li><li>Comandos rápidos da ferramenta ativa.</li></ul><h3 id="exemplo-15" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-15" aria-label="Permalink to “Exemplo”">​</a></h3><p>Ao selecionar a ferramenta de mover (<strong>Move Tool</strong>), a barra pode exibir atalhos específicos para movimentação de objetos.</p><hr><h2 id="exibicao-com-alt" tabindex="-1">Exibição com Alt <a class="header-anchor" href="#exibicao-com-alt" aria-label="Permalink to “Exibição com Alt”">​</a></h2><p>Em editores que possuem <strong>Toolbar (Barra de Ferramentas)</strong>, pressionar:</p><h3 id="windows-e-linux" tabindex="-1">Windows e Linux <a class="header-anchor" href="#windows-e-linux" aria-label="Permalink to “Windows e Linux”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Alt</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Option</span></span></code></pre></div><p>Mostra atalhos adicionais para troca rápida de ferramentas.</p><p>Isso permite visualizar rapidamente os comandos disponíveis sem precisar abrir menus.</p><hr><h2 id="preferencia-alt-click-tool-prompt" tabindex="-1">Preferência Alt Click Tool Prompt <a class="header-anchor" href="#preferencia-alt-click-tool-prompt" aria-label="Permalink to “Preferência Alt Click Tool Prompt”">​</a></h2><p>Essa funcionalidade pode ser desativada em:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Preferences → Keymap → Alt Click Tool Prompt</span></span></code></pre></div><p>Quando desativada, o Blender deixa de mostrar os atalhos ao pressionar <strong>Alt</strong>.</p><hr><h1 id="_2-mensagens-de-status" tabindex="-1">2. Mensagens de Status <a class="header-anchor" href="#_2-mensagens-de-status" aria-label="Permalink to “2. Mensagens de Status”">​</a></h1><p>A região central da barra apresenta informações temporárias sobre o sistema.</p><p>Essas mensagens ajudam o usuário a acompanhar operações e eventos.</p><hr><h2 id="tarefas-em-execucao" tabindex="-1">Tarefas em Execução <a class="header-anchor" href="#tarefas-em-execucao" aria-label="Permalink to “Tarefas em Execução”">​</a></h2><p>Quando o Blender executa uma tarefa demorada, a Status Bar exibe uma barra de progresso.</p><h3 id="exemplos-3" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-3" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Renderização</li><li>Bake de texturas</li><li>Simulações físicas</li><li>Processamento de dados</li></ul><h3 id="informacoes-exibidas" tabindex="-1">Informações exibidas <a class="header-anchor" href="#informacoes-exibidas" aria-label="Permalink to “Informações exibidas”">​</a></h3><p>A barra mostra:</p><ul><li>Percentual concluído.</li><li>Progresso visual.</li><li>Estimativa de tempo restante.</li></ul><p>Ao passar o cursor sobre a barra, o Blender exibe uma previsão do tempo necessário para concluir a tarefa.</p><hr><h2 id="cancelamento" tabindex="-1">Cancelamento <a class="header-anchor" href="#cancelamento" aria-label="Permalink to “Cancelamento”">​</a></h2><p>Tarefas em execução podem ser interrompidas através do botão de cancelamento.</p><p>Isso é útil quando:</p><ul><li>O render está demorando demais.</li><li>Foi usada uma configuração incorreta.</li><li>O usuário deseja interromper o processamento.</li></ul><hr><h2 id="mensagens-informativas" tabindex="-1">Mensagens Informativas <a class="header-anchor" href="#mensagens-informativas" aria-label="Permalink to “Mensagens Informativas”">​</a></h2><p>A barra também exibe notificações rápidas.</p><h3 id="exemplos-4" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-4" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Arquivo salvo com sucesso.</li><li>Configuração aplicada.</li><li>Operação concluída.</li><li>Avisos do sistema.</li></ul><p>Essas mensagens desaparecem automaticamente após alguns segundos.</p><hr><h2 id="visualizacao-completa" tabindex="-1">Visualização Completa <a class="header-anchor" href="#visualizacao-completa" aria-label="Permalink to “Visualização Completa”">​</a></h2><p>Ao clicar na mensagem, ela pode ser aberta no <strong>Info Editor</strong>, permitindo visualizar mais detalhes sobre a operação realizada.</p><hr><h1 id="_3-informacoes-de-recursos" tabindex="-1">3. Informações de Recursos <a class="header-anchor" href="#_3-informacoes-de-recursos" aria-label="Permalink to “3. Informações de Recursos”">​</a></h1><p>O lado direito da Status Bar apresenta informações técnicas e estatísticas sobre o projeto.</p><p>O usuário pode personalizar quais informações aparecem:</p><ul><li>Clicando com o botão direito na Status Bar.</li><li>Ajustando as preferências do Blender.</li></ul><hr><h1 id="estatisticas-da-cena-scene-statistics" tabindex="-1">Estatísticas da Cena (Scene Statistics) <a class="header-anchor" href="#estatisticas-da-cena-scene-statistics" aria-label="Permalink to “Estatísticas da Cena (Scene Statistics)”">​</a></h1><p>Mostra dados sobre a cena atualmente ativa.</p><hr><h2 id="collection" tabindex="-1">Collection <a class="header-anchor" href="#collection" aria-label="Permalink to “Collection”">​</a></h2><p>Exibe o nome da coleção ativa.</p><h3 id="exemplo-16" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-16" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Collection: Ambiente</span></span></code></pre></div><p>Coleções são grupos utilizados para organizar objetos.</p><hr><h2 id="active-object" tabindex="-1">Active Object <a class="header-anchor" href="#active-object" aria-label="Permalink to “Active Object”">​</a></h2><p>Mostra o objeto atualmente selecionado.</p><h3 id="exemplo-17" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-17" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Active Object: Cube</span></span></code></pre></div><p>Isso permite identificar rapidamente qual objeto está sendo editado.</p><hr><h2 id="geometry" tabindex="-1">Geometry <a class="header-anchor" href="#geometry" aria-label="Permalink to “Geometry”">​</a></h2><p>Mostra informações geométricas da cena.</p><p>Dependendo do modo utilizado, podem ser ser exibidos:</p><ul><li>Número de vértices.</li><li>Número de arestas.</li><li>Número de faces.</li><li>Número de triângulos.</li><li>Número de ossos (Armatures).</li></ul><p>Esses dados são úteis para avaliar a complexidade do modelo.</p><hr><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to “Objects”">​</a></h2><p>Exibe:</p><ul><li>Quantidade de objetos selecionados.</li><li>Quantidade total de objetos da cena.</li></ul><h3 id="exemplo-18" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-18" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Objects: 5 / 128</span></span></code></pre></div><p>Significa:</p><ul><li>5 objetos selecionados.</li><li>128 objetos na cena.</li></ul><hr><h1 id="duracao-da-cena-scene-duration" tabindex="-1">Duração da Cena (Scene Duration) <a class="header-anchor" href="#duracao-da-cena-scene-duration" aria-label="Permalink to “Duração da Cena (Scene Duration)”">​</a></h1><p>Apresenta informações sobre a animação.</p><p>Exibe:</p><ul><li>Quadro atual.</li><li>Número total de quadros.</li><li>Tempo total da animação.</li></ul><h3 id="exemplo-19" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-19" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Frame: 120 / 250</span></span></code></pre></div><p>Esses valores ajudam no controle de animações e simulações.</p><hr><h2 id="formato-do-tempo" tabindex="-1">Formato do Tempo <a class="header-anchor" href="#formato-do-tempo" aria-label="Permalink to “Formato do Tempo”">​</a></h2><p>O formato utilizado depende da configuração:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Timecode Style</span></span></code></pre></div><p>Ele pode exibir:</p><ul><li>Quadros.</li><li>Segundos.</li><li>Minutos.</li><li>Horas.</li></ul><hr><h1 id="memoria-do-sistema-system-memory" tabindex="-1">Memória do Sistema (System Memory) <a class="header-anchor" href="#memoria-do-sistema-system-memory" aria-label="Permalink to “Memória do Sistema (System Memory)”">​</a></h1><p>Mostra uma estimativa da quantidade de memória RAM utilizada pelo Blender.</p><h3 id="exemplo-20" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-20" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Memory: 3.2 GB</span></span></code></pre></div><p>Essa informação é importante para:</p><ul><li>Evitar travamentos.</li><li>Monitorar projetos pesados.</li><li>Avaliar desempenho.</li></ul><p>Quanto maior o projeto, maior tende a ser o consumo de memória.</p><hr><h1 id="atualizacoes-de-extensoes" tabindex="-1">Atualizações de Extensões <a class="header-anchor" href="#atualizacoes-de-extensoes" aria-label="Permalink to “Atualizações de Extensões”">​</a></h1><p>Exibe o número de extensões ou complementos que possuem atualizações disponíveis.</p><h3 id="exemplo-21" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-21" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Updates: 4</span></span></code></pre></div><p>Isso ajuda a manter os add-ons atualizados.</p><hr><h1 id="versao-do-blender" tabindex="-1">Versão do Blender <a class="header-anchor" href="#versao-do-blender" aria-label="Permalink to “Versão do Blender”">​</a></h1><p>Mostra a versão atualmente instalada e em execução.</p><h3 id="exemplo-22" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-22" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Blender 5.2 LTS</span></span></code></pre></div><p>Essa informação é importante para:</p><ul><li>Compatibilidade de projetos.</li><li>Suporte técnico.</li><li>Verificação de recursos disponíveis.</li></ul><h1 id="areas" tabindex="-1">Areas <a class="header-anchor" href="#areas" aria-label="Permalink to “Areas”">​</a></h1><p>As <strong>Areas (Áreas)</strong> são as divisões retangulares que compõem a interface do Blender. Cada área contém um <strong>Editor</strong>, responsável por uma função específica, como visualização 3D, edição de materiais, animação ou gerenciamento de objetos.</p><p>As áreas são a base da organização da interface e permitem personalizar completamente o ambiente de trabalho.</p><hr><h1 id="o-que-sao-areas" tabindex="-1">O que são Áreas? <a class="header-anchor" href="#o-que-sao-areas" aria-label="Permalink to “O que são Áreas?”">​</a></h1><p>A janela do Blender é dividida em vários retângulos chamados <strong>Áreas</strong>.</p><p>Cada área abriga um editor específico, por exemplo:</p><ul><li>3D Viewport</li><li>Outliner</li><li>Properties</li><li>Timeline</li><li>Shader Editor</li><li>Geometry Nodes Editor</li><li>UV Editor</li></ul><p>Os limites das áreas são identificados por seus cantos arredondados, que também servem como pontos de controle para reorganizar a interface.</p><hr><h1 id="relacao-entre-areas-editores-e-workspaces" tabindex="-1">Relação entre Áreas, Editores e Workspaces <a class="header-anchor" href="#relacao-entre-areas-editores-e-workspaces" aria-label="Permalink to “Relação entre Áreas, Editores e Workspaces”">​</a></h1><p>A organização da interface segue uma hierarquia:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Workspace</span></span>
<span class="line"><span> ├── Área</span></span>
<span class="line"><span> │    └── Editor</span></span>
<span class="line"><span> ├── Área</span></span>
<span class="line"><span> │    └── Editor</span></span>
<span class="line"><span> └── Área</span></span>
<span class="line"><span>      └── Editor</span></span></code></pre></div><h2 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to “Workspace”">​</a></h2><p>Conjunto de áreas voltado para uma tarefa específica.</p><h2 id="area" tabindex="-1">Área <a class="header-anchor" href="#area" aria-label="Permalink to “Área”">​</a></h2><p>Espaço reservado dentro da interface.</p><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to “Editor”">​</a></h2><p>Ferramenta exibida dentro da área.</p><h3 id="exemplo-23" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-23" aria-label="Permalink to “Exemplo”">​</a></h3><p>No workspace <strong>Layout</strong>:</p><ul><li>Área superior esquerda → 3D Viewport</li><li>Área superior direita → Outliner</li><li>Área inferior direita → Properties</li><li>Área inferior esquerda → Timeline</li></ul><hr><h1 id="atalhos-dependem-da-area-ativa" tabindex="-1">Atalhos Dependem da Área Ativa <a class="header-anchor" href="#atalhos-dependem-da-area-ativa" aria-label="Permalink to “Atalhos Dependem da Área Ativa”">​</a></h1><p>Embora alguns atalhos sejam globais, muitos funcionam apenas em determinados editores.</p><h3 id="exemplo-24" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-24" aria-label="Permalink to “Exemplo”">​</a></h3><p>Suponha que dois objetos estejam selecionados no Outliner.</p><p>Para juntá-los:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + J</span></span></code></pre></div><p>Esse atalho funciona apenas no <strong>3D Viewport</strong>.</p><p>Se o cursor estiver sobre o <strong>Outliner</strong>, o comando não será executado.</p><p>Por isso, a posição do mouse influencia diretamente quais atalhos estarão disponíveis.</p><hr><h1 id="personalizacao-das-bordas" tabindex="-1">Personalização das Bordas <a class="header-anchor" href="#personalizacao-das-bordas" aria-label="Permalink to “Personalização das Bordas”">​</a></h1><p>A espessura das bordas entre áreas pode ser alterada nas Preferências.</p><h3 id="configuracao" tabindex="-1">Configuração <a class="header-anchor" href="#configuracao" aria-label="Permalink to “Configuração”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Preferences → Interface → Border Width</span></span></code></pre></div><p>Isso facilita a seleção e o redimensionamento das áreas.</p><hr><h1 id="corner-handles" tabindex="-1">Corner Handles <a class="header-anchor" href="#corner-handles" aria-label="Permalink to “Corner Handles”">​</a></h1><p>Os cantos das áreas podem permanecer sempre visíveis.</p><p>Essa opção é especialmente útil em:</p><ul><li>Tablets</li><li>Notebooks touchscreen</li><li>Monitores sensíveis ao toque</li></ul><p>Facilitando operações de divisão e reorganização.</p><hr><h1 id="redimensionamento-de-areas" tabindex="-1">Redimensionamento de Áreas <a class="header-anchor" href="#redimensionamento-de-areas" aria-label="Permalink to “Redimensionamento de Áreas”">​</a></h1><p>As áreas podem ser redimensionadas livremente.</p><h2 id="como-fazer" tabindex="-1">Como fazer <a class="header-anchor" href="#como-fazer" aria-label="Permalink to “Como fazer”">​</a></h2><ol><li>Posicione o cursor sobre a borda entre duas áreas.</li><li>O cursor mudará para uma seta dupla.</li><li>Clique e arraste.</li></ol><hr><h2 id="ajuste-com-precisao" tabindex="-1">Ajuste com Precisão <a class="header-anchor" href="#ajuste-com-precisao" aria-label="Permalink to “Ajuste com Precisão”">​</a></h2><p>Segurando:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl</span></span></code></pre></div><p>o Blender encaixa automaticamente os tamanhos em posições mais convenientes.</p><p>Isso facilita a criação de layouts organizados.</p><hr><h1 id="docking-gerenciamento-de-areas" tabindex="-1">Docking (Gerenciamento de Áreas) <a class="header-anchor" href="#docking-gerenciamento-de-areas" aria-label="Permalink to “Docking (Gerenciamento de Áreas)”">​</a></h1><p>O termo <strong>Docking</strong> refere-se às ferramentas que permitem:</p><ul><li>Dividir áreas</li><li>Unir áreas</li><li>Trocar posições</li><li>Reorganizar a interface</li></ul><hr><h2 id="iniciando-o-docking" tabindex="-1">Iniciando o Docking <a class="header-anchor" href="#iniciando-o-docking" aria-label="Permalink to “Iniciando o Docking”">​</a></h2><p>Ao mover o cursor para um dos cantos de uma área, ele se transforma em:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+</span></span></code></pre></div><p><em>(crosshair)</em></p><p>A partir daí, basta manter o botão esquerdo pressionado e arrastar.</p><hr><h2 id="cancelamento-1" tabindex="-1">Cancelamento <a class="header-anchor" href="#cancelamento-1" aria-label="Permalink to “Cancelamento”">​</a></h2><p>Antes de soltar o mouse, é possível cancelar a operação usando:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Esc</span></span></code></pre></div><p>ou</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Botão Direito</span></span></code></pre></div><hr><h1 id="juntando-areas-join" tabindex="-1">Juntando Áreas (Join) <a class="header-anchor" href="#juntando-areas-join" aria-label="Permalink to “Juntando Áreas (Join)”">​</a></h1><p>Permite unir duas áreas em uma única.</p><h2 id="como-fazer-1" tabindex="-1">Como fazer <a class="header-anchor" href="#como-fazer-1" aria-label="Permalink to “Como fazer”">​</a></h2><ol><li>Clique em um canto.</li><li>Arraste em direção à segunda área.</li><li>Solte o mouse.</li></ol><p>As áreas envolvidas ficam destacadas durante a operação.</p><h3 id="vantagens" tabindex="-1">Vantagens <a class="header-anchor" href="#vantagens" aria-label="Permalink to “Vantagens”">​</a></h3><p>Útil para:</p><ul><li>Criar áreas maiores.</li><li>Dar mais espaço ao 3D Viewport.</li><li>Simplificar a interface.</li></ul><hr><h1 id="dividindo-areas-split" tabindex="-1">Dividindo Áreas (Split) <a class="header-anchor" href="#dividindo-areas-split" aria-label="Permalink to “Dividindo Áreas (Split)”">​</a></h1><p>Permite criar uma nova área.</p><hr><h2 id="divisao-vertical" tabindex="-1">Divisão Vertical <a class="header-anchor" href="#divisao-vertical" aria-label="Permalink to “Divisão Vertical”">​</a></h2><p>Arraste para:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Esquerda ou Direita</span></span></code></pre></div><p>Resultado:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>|     |</span></span>
<span class="line"><span>|     |</span></span></code></pre></div><hr><h2 id="divisao-horizontal" tabindex="-1">Divisão Horizontal <a class="header-anchor" href="#divisao-horizontal" aria-label="Permalink to “Divisão Horizontal”">​</a></h2><p>Arraste para:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Cima ou Baixo</span></span></code></pre></div><p>Resultado:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------</span></span>
<span class="line"><span>---------</span></span></code></pre></div><hr><h1 id="divisao-e-uniao-simultanea" tabindex="-1">Divisão e União Simultânea <a class="header-anchor" href="#divisao-e-uniao-simultanea" aria-label="Permalink to “Divisão e União Simultânea”">​</a></h1><p>O Blender permite:</p><ul><li>Dividir uma área.</li><li>Juntar outra área.</li></ul><p>Tudo em uma única operação de arrastar.</p><hr><h1 id="substituir-uma-area" tabindex="-1">Substituir uma Área <a class="header-anchor" href="#substituir-uma-area" aria-label="Permalink to “Substituir uma Área”">​</a></h1><p>Se uma área for arrastada para o centro de outra:</p><p>O Blender substitui o conteúdo da área de destino.</p><p>Isso permite reorganizar rapidamente a interface.</p><hr><h1 id="opcoes-de-area" tabindex="-1">Opções de Área <a class="header-anchor" href="#opcoes-de-area" aria-label="Permalink to “Opções de Área”">​</a></h1><p>Ao clicar com:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Botão Direito na borda</span></span></code></pre></div><p>abre-se o menu de opções da área.</p><hr><h2 id="vertical-split" tabindex="-1">Vertical Split <a class="header-anchor" href="#vertical-split" aria-label="Permalink to “Vertical Split”">​</a></h2><p>Divide verticalmente.</p><hr><h2 id="horizontal-split" tabindex="-1">Horizontal Split <a class="header-anchor" href="#horizontal-split" aria-label="Permalink to “Horizontal Split”">​</a></h2><p>Divide horizontalmente.</p><h3 id="durante-a-operacao" tabindex="-1">Durante a operação <a class="header-anchor" href="#durante-a-operacao" aria-label="Permalink to “Durante a operação”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tab</span></span></code></pre></div><p>alterna entre os modos vertical e horizontal.</p><hr><h2 id="join-up-down-left-right" tabindex="-1">Join Up / Down / Left / Right <a class="header-anchor" href="#join-up-down-left-right" aria-label="Permalink to “Join Up / Down / Left / Right”">​</a></h2><p>Une áreas em uma direção específica.</p><h3 id="exemplos-5" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-5" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Join Up</li><li>Join Down</li><li>Join Left</li><li>Join Right</li></ul><hr><h2 id="swap-areas" tabindex="-1">Swap Areas <a class="header-anchor" href="#swap-areas" aria-label="Permalink to “Swap Areas”">​</a></h2><p>Troca a posição de duas áreas vizinhas.</p><p>Muito útil quando a organização da interface não está ideal.</p><hr><h1 id="troca-de-conteudo-entre-areas" tabindex="-1">Troca de Conteúdo Entre Áreas <a class="header-anchor" href="#troca-de-conteudo-entre-areas" aria-label="Permalink to “Troca de Conteúdo Entre Áreas”">​</a></h1><p>O Blender permite trocar o conteúdo de duas áreas sem alterar seus tamanhos.</p><h2 id="procedimento" tabindex="-1">Procedimento <a class="header-anchor" href="#procedimento" aria-label="Permalink to “Procedimento”">​</a></h2><p>Segure:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl</span></span></code></pre></div><p>Clique em um dos cantos da área.</p><p>Arraste até a área desejada.</p><p>Solte o mouse.</p><h3 id="resultado" tabindex="-1">Resultado <a class="header-anchor" href="#resultado" aria-label="Permalink to “Resultado”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Viewport ↔ Outliner</span></span></code></pre></div><p>Os dois editores trocam de lugar.</p><p>Não precisam estar lado a lado.</p><p>Apenas precisam estar na mesma janela.</p><hr><h1 id="maximize-area" tabindex="-1">Maximize Area <a class="header-anchor" href="#maximize-area" aria-label="Permalink to “Maximize Area”">​</a></h1><h3 id="atalho" tabindex="-1">Atalho <a class="header-anchor" href="#atalho" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + Espaço</span></span></code></pre></div><h3 id="menu" tabindex="-1">Menu <a class="header-anchor" href="#menu" aria-label="Permalink to “Menu”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>View → Area → Toggle Maximize Area</span></span></code></pre></div><hr><h2 id="funcao" tabindex="-1">Função <a class="header-anchor" href="#funcao" aria-label="Permalink to “Função”">​</a></h2><p>Expande a área selecionada para ocupar praticamente toda a janela.</p><p>Mantém visíveis:</p><ul><li>Topbar</li><li>Status Bar</li></ul><hr><h2 id="beneficios" tabindex="-1">Benefícios <a class="header-anchor" href="#beneficios" aria-label="Permalink to “Benefícios”">​</a></h2><p>Excelente para:</p><ul><li>Modelagem</li><li>Escultura</li><li>Edição de materiais</li><li>Programação</li></ul><p>Quando é necessário mais espaço.</p><hr><h2 id="no-3d-viewport" tabindex="-1">No 3D Viewport <a class="header-anchor" href="#no-3d-viewport" aria-label="Permalink to “No 3D Viewport”">​</a></h2><p>Ao maximizar, o Blender oculta temporariamente:</p><ul><li>Gizmos de navegação</li><li>Sobreposições de texto</li><li>Estatísticas</li></ul><p>Isso aumenta a área útil de trabalho.</p><hr><h2 id="restaurar" tabindex="-1">Restaurar <a class="header-anchor" href="#restaurar" aria-label="Permalink to “Restaurar”">​</a></h2><p>Pressione novamente:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + Espaço</span></span></code></pre></div><p>ou clique em:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Back to Previous</span></span></code></pre></div><p>na Topbar.</p><hr><h1 id="restore-area" tabindex="-1">Restore Area <a class="header-anchor" href="#restore-area" aria-label="Permalink to “Restore Area”">​</a></h1><h3 id="atalho-1" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-1" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + Espaço</span></span></code></pre></div><p>Retorna a área maximizada ao tamanho original.</p><p>Restaura completamente o layout anterior.</p><hr><h1 id="focus-mode" tabindex="-1">Focus Mode <a class="header-anchor" href="#focus-mode" aria-label="Permalink to “Focus Mode”">​</a></h1><h3 id="atalho-2" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-2" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + Alt + Espaço</span></span></code></pre></div><h3 id="menu-1" tabindex="-1">Menu <a class="header-anchor" href="#menu-1" aria-label="Permalink to “Menu”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>View → Area → Focus Mode</span></span></code></pre></div><hr><h2 id="funcao-1" tabindex="-1">Função <a class="header-anchor" href="#funcao-1" aria-label="Permalink to “Função”">​</a></h2><p>Ocupa toda a janela disponível com o editor ativo.</p><p>Diferente do <strong>Maximize Area</strong>, ele esconde:</p><ul><li>Topbar</li><li>Status Bar</li><li>Barras laterais</li><li>Cabeçalhos</li><li>Regiões secundárias</li></ul><hr><h2 id="vantagem-1" tabindex="-1">Vantagem <a class="header-anchor" href="#vantagem-1" aria-label="Permalink to “Vantagem”">​</a></h2><p>Oferece o máximo espaço possível para o editor.</p><p>Ideal para:</p><ul><li>Escultura detalhada</li><li>Pintura de texturas</li><li>Modelagem complexa</li><li>Análise de renderizações</li></ul><hr><h2 id="retornar-ao-normal" tabindex="-1">Retornar ao Normal <a class="header-anchor" href="#retornar-ao-normal" aria-label="Permalink to “Retornar ao Normal”">​</a></h2><p>Use novamente:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + Alt + Espaço</span></span></code></pre></div><p>ou clique no ícone de restauração exibido ao passar o mouse sobre a área.</p><hr><h1 id="duplicate-area-into-new-window" tabindex="-1">Duplicate Area into New Window <a class="header-anchor" href="#duplicate-area-into-new-window" aria-label="Permalink to “Duplicate Area into New Window”">​</a></h1><h3 id="menu-2" tabindex="-1">Menu <a class="header-anchor" href="#menu-2" aria-label="Permalink to “Menu”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>View → Area → Duplicate Area into New Window</span></span></code></pre></div><hr><h2 id="funcao-2" tabindex="-1">Função <a class="header-anchor" href="#funcao-2" aria-label="Permalink to “Função”">​</a></h2><p>Cria uma nova janela flutuante contendo uma cópia da área atual.</p><p>A nova janela permanece conectada à mesma sessão do Blender.</p><hr><h2 id="aplicacoes" tabindex="-1">Aplicações <a class="header-anchor" href="#aplicacoes" aria-label="Permalink to “Aplicações”">​</a></h2><p>Muito útil para:</p><ul><li>Trabalhar com dois monitores.</li><li>Manter o Outliner aberto em uma tela.</li><li>Visualizar o Render Result em outra tela.</li><li>Deixar o Shader Editor separado.</li><li>Monitorar animações enquanto modela.</li></ul><h1 id="regions" tabindex="-1">Regions <a class="header-anchor" href="#regions" aria-label="Permalink to “Regions”">​</a></h1><p>As <strong>Regions (Regiões)</strong> são subdivisões internas de cada editor do Blender. Enquanto as <strong>Áreas (Areas)</strong> definem o espaço ocupado por um editor na interface, as <strong>Regiões</strong> organizam os elementos internos desse editor, como menus, ferramentas, painéis e controles.</p><p>Cada editor possui pelo menos uma região principal e pode conter várias regiões adicionais dependendo de sua função.</p><hr><h1 id="o-que-sao-regioes" tabindex="-1">O que são Regiões? <a class="header-anchor" href="#o-que-sao-regioes" aria-label="Permalink to “O que são Regiões?”">​</a></h1><p>Todo editor do Blender é dividido em regiões.</p><p>Essas regiões servem para organizar:</p><ul><li>Menus</li><li>Ferramentas</li><li>Painéis</li><li>Configurações</li><li>Informações</li><li>Widgets de controle</li></ul><h3 id="exemplo-no-3d-viewport" tabindex="-1">Exemplo no 3D Viewport <a class="header-anchor" href="#exemplo-no-3d-viewport" aria-label="Permalink to “Exemplo no 3D Viewport”">​</a></h3><ul><li>Cabeçalho (Header)</li><li>Região Principal (Main Region)</li><li>Barra de Ferramentas (Toolbar)</li><li>Barra Lateral (Sidebar)</li><li>Painel <strong>Adjust Last Operation</strong></li></ul><hr><h1 id="estrutura-geral-das-regioes" tabindex="-1">Estrutura Geral das Regiões <a class="header-anchor" href="#estrutura-geral-das-regioes" aria-label="Permalink to “Estrutura Geral das Regiões”">​</a></h1><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Editor</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Header</span></span>
<span class="line"><span>├── Tool Settings</span></span>
<span class="line"><span>├── Toolbar</span></span>
<span class="line"><span>├── Main Region</span></span>
<span class="line"><span>├── Sidebar</span></span>
<span class="line"><span>├── Footer</span></span>
<span class="line"><span>└── Painéis Temporários</span></span></code></pre></div><p>Cada editor possui uma combinação diferente dessas regiões.</p><hr><h1 id="_1-regiao-principal-main-region" tabindex="-1">1. Região Principal (Main Region) <a class="header-anchor" href="#_1-regiao-principal-main-region" aria-label="Permalink to “1. Região Principal (Main Region)”">​</a></h1><p>É a região mais importante do editor.</p><h3 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to “Características”">​</a></h3><ul><li>Sempre existe.</li><li>Nunca pode ser removida.</li><li>Ocupa a maior parte do espaço disponível.</li></ul><h2 id="funcao-3" tabindex="-1">Função <a class="header-anchor" href="#funcao-3" aria-label="Permalink to “Função”">​</a></h2><p>A região principal contém o conteúdo central do editor.</p><h3 id="no-3d-viewport-1" tabindex="-1">No 3D Viewport <a class="header-anchor" href="#no-3d-viewport-1" aria-label="Permalink to “No 3D Viewport”">​</a></h3><p>Mostra:</p><ul><li>Objetos 3D</li><li>Luzes</li><li>Câmeras</li><li>Malhas</li></ul><h3 id="no-shader-editor" tabindex="-1">No Shader Editor <a class="header-anchor" href="#no-shader-editor" aria-label="Permalink to “No Shader Editor”">​</a></h3><p>Mostra:</p><ul><li>Nós (Nodes)</li><li>Conexões entre materiais</li></ul><h3 id="no-timeline" tabindex="-1">No Timeline <a class="header-anchor" href="#no-timeline" aria-label="Permalink to “No Timeline”">​</a></h3><p>Mostra:</p><ul><li>Quadros da animação</li><li>Keyframes</li></ul><hr><h1 id="_2-cabecalho-header" tabindex="-1">2. Cabeçalho (Header) <a class="header-anchor" href="#_2-cabecalho-header" aria-label="Permalink to “2. Cabeçalho (Header)”">​</a></h1><p>O <strong>Header</strong> é uma faixa horizontal localizada na parte superior ou inferior do editor.</p><p>Todos os editores possuem um cabeçalho.</p><h2 id="funcoes" tabindex="-1">Funções <a class="header-anchor" href="#funcoes" aria-label="Permalink to “Funções”">​</a></h2><p>Contém:</p><ul><li>Menus</li><li>Ferramentas</li><li>Botões de acesso rápido</li><li>Configurações do editor</li></ul><p>O conteúdo muda conforme:</p><ul><li>Tipo de editor</li><li>Objeto selecionado</li><li>Modo ativo</li></ul><hr><h2 id="menu-de-contexto-do-header" tabindex="-1">Menu de Contexto do Header <a class="header-anchor" href="#menu-de-contexto-do-header" aria-label="Permalink to “Menu de Contexto do Header”">​</a></h2><p>Clique com:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Botão Direito (RMB)</span></span></code></pre></div><p>sobre o cabeçalho.</p><hr><h3 id="show-header" tabindex="-1">Show Header <a class="header-anchor" href="#show-header" aria-label="Permalink to “Show Header”">​</a></h3><p>Mostra ou oculta o cabeçalho.</p><p>Quando ocultado, uma pequena seta aparece para restaurá-lo.</p><hr><h3 id="show-tool-settings" tabindex="-1">Show Tool Settings <a class="header-anchor" href="#show-tool-settings" aria-label="Permalink to “Show Tool Settings”">​</a></h3><p>Mostra ou oculta a região <strong>Tool Settings</strong>.</p><hr><h3 id="show-menus" tabindex="-1">Show Menus <a class="header-anchor" href="#show-menus" aria-label="Permalink to “Show Menus”">​</a></h3><p>Mostra ou oculta os menus do cabeçalho.</p><hr><h3 id="flip-to-bottom-top" tabindex="-1">Flip to Bottom / Top <a class="header-anchor" href="#flip-to-bottom-top" aria-label="Permalink to “Flip to Bottom / Top”">​</a></h3><p>Move o cabeçalho entre:</p><ul><li>Parte superior</li><li>Parte inferior</li></ul><p>do editor.</p><hr><h3 id="vertical-horizontal-split" tabindex="-1">Vertical / Horizontal Split <a class="header-anchor" href="#vertical-horizontal-split" aria-label="Permalink to “Vertical / Horizontal Split”">​</a></h3><p>Permite dividir áreas diretamente a partir do cabeçalho.</p><h3 id="atalho-3" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-3" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tab</span></span></code></pre></div><p>alterna entre:</p><ul><li>Divisão vertical</li><li>Divisão horizontal</li></ul><hr><h3 id="maximize-area-focus-mode" tabindex="-1">Maximize Area / Focus Mode <a class="header-anchor" href="#maximize-area-focus-mode" aria-label="Permalink to “Maximize Area / Focus Mode”">​</a></h3><p>Acessa os modos de ampliação da área.</p><hr><h3 id="duplicate-area-into-new-window-1" tabindex="-1">Duplicate Area into New Window <a class="header-anchor" href="#duplicate-area-into-new-window-1" aria-label="Permalink to “Duplicate Area into New Window”">​</a></h3><p>Cria uma nova janela contendo uma cópia do editor.</p><hr><h3 id="close-area" tabindex="-1">Close Area <a class="header-anchor" href="#close-area" aria-label="Permalink to “Close Area”">​</a></h3><p>Fecha a área atual e expande uma área vizinha para ocupar seu espaço.</p><hr><h1 id="_3-toolbar-barra-de-ferramentas" tabindex="-1">3. Toolbar (Barra de Ferramentas) <a class="header-anchor" href="#_3-toolbar-barra-de-ferramentas" aria-label="Permalink to “3. Toolbar (Barra de Ferramentas)”">​</a></h1><p>Localizada normalmente no lado esquerdo do editor.</p><p>Contém ferramentas interativas.</p><hr><h2 id="exemplos-de-ferramentas" tabindex="-1">Exemplos de Ferramentas <a class="header-anchor" href="#exemplos-de-ferramentas" aria-label="Permalink to “Exemplos de Ferramentas”">​</a></h2><h3 id="no-3d-viewport-2" tabindex="-1">No 3D Viewport <a class="header-anchor" href="#no-3d-viewport-2" aria-label="Permalink to “No 3D Viewport”">​</a></h3><ul><li>Move</li><li>Rotate</li><li>Scale</li><li>Extrude</li><li>Annotate</li></ul><h3 id="atalho-4" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-4" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>T</span></span></code></pre></div><p>Mostra ou oculta a Toolbar.</p><hr><h1 id="_4-tool-settings" tabindex="-1">4. Tool Settings <a class="header-anchor" href="#_4-tool-settings" aria-label="Permalink to “4. Tool Settings”">​</a></h1><p>É uma faixa horizontal semelhante ao Header.</p><p>Pode ficar:</p><ul><li>Na parte superior</li><li>Na parte inferior</li></ul><p>do editor.</p><hr><h2 id="funcao-4" tabindex="-1">Função <a class="header-anchor" href="#funcao-4" aria-label="Permalink to “Função”">​</a></h2><p>Mostra configurações específicas da ferramenta atualmente selecionada.</p><h3 id="exemplo-25" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-25" aria-label="Permalink to “Exemplo”">​</a></h3><p>Se a ferramenta ativa for <strong>Extrude</strong>, essa região exibirá opções relacionadas à extrusão.</p><hr><h2 id="personalizacao" tabindex="-1">Personalização <a class="header-anchor" href="#personalizacao" aria-label="Permalink to “Personalização”">​</a></h2><p>Pode ser:</p><ul><li>Ocultada</li><li>Movida</li></ul><p>através do menu de contexto do Header.</p><hr><h1 id="_5-adjust-last-operation" tabindex="-1">5. Adjust Last Operation <a class="header-anchor" href="#_5-adjust-last-operation" aria-label="Permalink to “5. Adjust Last Operation”">​</a></h1><p>É um painel temporário exibido após executar uma operação.</p><h2 id="funcao-5" tabindex="-1">Função <a class="header-anchor" href="#funcao-5" aria-label="Permalink to “Função”">​</a></h2><p>Permite modificar parâmetros da última ação realizada.</p><h3 id="exemplo-26" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-26" aria-label="Permalink to “Exemplo”">​</a></h3><p>Após adicionar um cubo:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Shift + A → Mesh → Cube</span></span></code></pre></div><p>O painel permite alterar:</p><ul><li>Tamanho</li><li>Localização</li><li>Rotação</li></ul><p>sem precisar recriar o objeto.</p><hr><h2 id="vantagem-2" tabindex="-1">Vantagem <a class="header-anchor" href="#vantagem-2" aria-label="Permalink to “Vantagem”">​</a></h2><p>Facilita ajustes rápidos imediatamente após uma operação.</p><hr><h1 id="_6-sidebar-barra-lateral" tabindex="-1">6. Sidebar (Barra Lateral) <a class="header-anchor" href="#_6-sidebar-barra-lateral" aria-label="Permalink to “6. Sidebar (Barra Lateral)”">​</a></h1><p>A Sidebar fica normalmente no lado direito do editor.</p><hr><h2 id="conteudo" tabindex="-1">Conteúdo <a class="header-anchor" href="#conteudo" aria-label="Permalink to “Conteúdo”">​</a></h2><p>Contém painéis com:</p><ul><li>Configurações do objeto</li><li>Ferramentas adicionais</li><li>Informações do editor</li><li>Configurações da cena</li></ul><h3 id="atalho-5" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-5" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>N</span></span></code></pre></div><p>Mostra ou oculta a Sidebar.</p><hr><h2 id="utilizacao" tabindex="-1">Utilização <a class="header-anchor" href="#utilizacao" aria-label="Permalink to “Utilização”">​</a></h2><p>É uma das regiões mais usadas durante:</p><ul><li>Modelagem</li><li>Animação</li><li>Escultura</li><li>Renderização</li></ul><hr><h1 id="_7-footer-rodape" tabindex="-1">7. Footer (Rodapé) <a class="header-anchor" href="#_7-footer-rodape" aria-label="Permalink to “7. Footer (Rodapé)”">​</a></h1><p>Alguns editores possuem um rodapé.</p><p>Ele aparece na parte superior ou inferior do editor.</p><hr><h2 id="funcao-6" tabindex="-1">Função <a class="header-anchor" href="#funcao-6" aria-label="Permalink to “Função”">​</a></h2><p>Exibe informações relacionadas ao editor atual.</p><h3 id="em-editores-de-animacao" tabindex="-1">Em editores de animação <a class="header-anchor" href="#em-editores-de-animacao" aria-label="Permalink to “Em editores de animação”">​</a></h3><p>O Footer contém controles de:</p><ul><li>Reprodução</li><li>Keyframes</li><li>Auto Keying</li><li>Navegação temporal</li></ul><hr><h2 id="recursos-disponiveis" tabindex="-1">Recursos Disponíveis <a class="header-anchor" href="#recursos-disponiveis" aria-label="Permalink to “Recursos Disponíveis”">​</a></h2><h3 id="controle-de-reproducao" tabindex="-1">Controle de Reprodução <a class="header-anchor" href="#controle-de-reproducao" aria-label="Permalink to “Controle de Reprodução”">​</a></h3><ul><li>Play</li><li>Pause</li><li>Stop</li></ul><h3 id="insercao-de-keyframes" tabindex="-1">Inserção de Keyframes <a class="header-anchor" href="#insercao-de-keyframes" aria-label="Permalink to “Inserção de Keyframes”">​</a></h3><ul><li>Criação automática</li><li>Gerenciamento de conjuntos de keyframes</li></ul><h3 id="navegacao" tabindex="-1">Navegação <a class="header-anchor" href="#navegacao" aria-label="Permalink to “Navegação”">​</a></h3><ul><li>Avanço de quadros</li><li>Retrocesso</li><li>Controle da Timeline</li></ul><h3 id="ajuste-de-intervalos" tabindex="-1">Ajuste de Intervalos <a class="header-anchor" href="#ajuste-de-intervalos" aria-label="Permalink to “Ajuste de Intervalos”">​</a></h3><p>Permite definir:</p><ul><li>Início da animação</li><li>Final da animação</li><li>Faixas de pré-visualização</li></ul><hr><h1 id="organizacao-das-regioes" tabindex="-1">Organização das Regiões <a class="header-anchor" href="#organizacao-das-regioes" aria-label="Permalink to “Organização das Regiões”">​</a></h1><p>As regiões podem ser:</p><ul><li>Roladas</li><li>Redimensionadas</li><li>Ocultadas</li><li>Escaladas</li></ul><hr><h1 id="rolagem-scrolling" tabindex="-1">Rolagem (Scrolling) <a class="header-anchor" href="#rolagem-scrolling" aria-label="Permalink to “Rolagem (Scrolling)”">​</a></h1><p>Regiões podem ser percorridas usando:</p><h3 id="botao-do-meio-mmb" tabindex="-1">Botão do Meio (MMB) <a class="header-anchor" href="#botao-do-meio-mmb" aria-label="Permalink to “Botão do Meio (MMB)”">​</a></h3><p>Clique e arraste.</p><h3 id="roda-do-mouse" tabindex="-1">Roda do Mouse <a class="header-anchor" href="#roda-do-mouse" aria-label="Permalink to “Roda do Mouse”">​</a></h3><p>Quando o editor não possui zoom próprio.</p><hr><h2 id="barras-de-rolagem-avancadas" tabindex="-1">Barras de Rolagem Avançadas <a class="header-anchor" href="#barras-de-rolagem-avancadas" aria-label="Permalink to “Barras de Rolagem Avançadas”">​</a></h2><p>Algumas regiões possuem barras especiais com controles extras.</p><p>Esses controles permitem:</p><ul><li>Ampliar visualização</li><li>Reduzir visualização</li><li>Ajustar detalhes exibidos</li></ul><h3 id="atalho-6" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-6" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + MMB</span></span></code></pre></div><p>Permite ajustar rapidamente:</p><ul><li>Escala horizontal</li><li>Escala vertical</li></ul><hr><h1 id="redimensionamento" tabindex="-1">Redimensionamento <a class="header-anchor" href="#redimensionamento" aria-label="Permalink to “Redimensionamento”">​</a></h1><p>As regiões podem ser redimensionadas da mesma forma que as áreas.</p><p>Basta arrastar suas bordas.</p><hr><h1 id="ocultar-regioes" tabindex="-1">Ocultar Regiões <a class="header-anchor" href="#ocultar-regioes" aria-label="Permalink to “Ocultar Regiões”">​</a></h1><p>Para ocultar uma região:</p><ol><li>Arraste sua borda até o mínimo.</li><li>A região desaparecerá.</li></ol><hr><h2 id="restaurar-1" tabindex="-1">Restaurar <a class="header-anchor" href="#restaurar-1" aria-label="Permalink to “Restaurar”">​</a></h2><p>Uma pequena seta aparecerá.</p><p>Clique nela para exibir novamente a região.</p><hr><h1 id="escala-das-regioes" tabindex="-1">Escala das Regiões <a class="header-anchor" href="#escala-das-regioes" aria-label="Permalink to “Escala das Regiões”">​</a></h1><p>Algumas regiões permitem alterar o tamanho dos elementos internos.</p><h3 id="exemplo-27" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-27" aria-label="Permalink to “Exemplo”">​</a></h3><p>Toolbar.</p><hr><h2 id="metodos" tabindex="-1">Métodos <a class="header-anchor" href="#metodos" aria-label="Permalink to “Métodos”">​</a></h2><h3 id="mouse" tabindex="-1">Mouse <a class="header-anchor" href="#mouse" aria-label="Permalink to “Mouse”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + MMB</span></span></code></pre></div><p>Arrastar dentro da região.</p><h3 id="teclado-numerico" tabindex="-1">Teclado Numérico <a class="header-anchor" href="#teclado-numerico" aria-label="Permalink to “Teclado Numérico”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Numpad +</span></span></code></pre></div><p>Aumenta a escala.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Numpad -</span></span></code></pre></div><p>Diminui a escala.</p><h3 id="reset" tabindex="-1">Reset <a class="header-anchor" href="#reset" aria-label="Permalink to “Reset”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Home</span></span></code></pre></div><p>Retorna à escala padrão.</p><hr><h1 id="asset-shelf" tabindex="-1">Asset Shelf <a class="header-anchor" href="#asset-shelf" aria-label="Permalink to “Asset Shelf”">​</a></h1><p>A <strong>Asset Shelf (Prateleira de Ativos)</strong> é uma região utilizada para acessar ativos armazenados.</p><h3 id="exemplos-6" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-6" aria-label="Permalink to “Exemplos”">​</a></h3><ul><li>Materiais</li><li>Brushes</li><li>Objetos</li><li>Poses</li></ul><hr><h2 id="pesquisa-de-assets" tabindex="-1">Pesquisa de Assets <a class="header-anchor" href="#pesquisa-de-assets" aria-label="Permalink to “Pesquisa de Assets”">​</a></h2><h3 id="atalho-7" tabindex="-1">Atalho <a class="header-anchor" href="#atalho-7" aria-label="Permalink to “Atalho”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + F</span></span></code></pre></div><p>Permite pesquisar ativos pelo nome.</p><hr><h2 id="catalogos-como-abas" tabindex="-1">Catálogos como Abas <a class="header-anchor" href="#catalogos-como-abas" aria-label="Permalink to “Catálogos como Abas”">​</a></h2><p>Os catálogos podem ser exibidos em formato de abas.</p><p>Cada aba mostra:</p><ul><li>Seus próprios ativos.</li><li>Os ativos das subcategorias.</li></ul><p>Isso facilita a organização de bibliotecas grandes.</p><hr><h2 id="opcoes-de-exibicao" tabindex="-1">Opções de Exibição <a class="header-anchor" href="#opcoes-de-exibicao" aria-label="Permalink to “Opções de Exibição”">​</a></h2><p>A Asset Shelf permite:</p><h3 id="alterar-tamanho-dos-itens" tabindex="-1">Alterar tamanho dos itens <a class="header-anchor" href="#alterar-tamanho-dos-itens" aria-label="Permalink to “Alterar tamanho dos itens”">​</a></h3><p>Aumentar ou reduzir miniaturas.</p><h3 id="mostrar-nomes" tabindex="-1">Mostrar nomes <a class="header-anchor" href="#mostrar-nomes" aria-label="Permalink to “Mostrar nomes”">​</a></h3><p>Exibir o nome dos ativos diretamente na prateleira.</p><h3 id="ajustar-altura" tabindex="-1">Ajustar altura <a class="header-anchor" href="#ajustar-altura" aria-label="Permalink to “Ajustar altura”">​</a></h3><p>Permite exibir várias linhas de ativos.</p><p>Basta arrastar sua borda superior.</p><hr><h2 id="filtro-por-ferramenta-ativa" tabindex="-1">Filtro por Ferramenta Ativa <a class="header-anchor" href="#filtro-por-ferramenta-ativa" aria-label="Permalink to “Filtro por Ferramenta Ativa”">​</a></h2><h3 id="opcao" tabindex="-1">Opção <a class="header-anchor" href="#opcao" aria-label="Permalink to “Opção”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>By Active Tool</span></span></code></pre></div><p>Mostra apenas os ativos compatíveis com a ferramenta atualmente selecionada.</p><h3 id="exemplo-28" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-28" aria-label="Permalink to “Exemplo”">​</a></h3><p>Ao usar um pincel de escultura, apenas brushes relevantes serão exibidos.</p><h1 id="tabs-e-panels" tabindex="-1">Tabs e Panels <a class="header-anchor" href="#tabs-e-panels" aria-label="Permalink to “Tabs e Panels”">​</a></h1><p>As <strong>Tabs (Abas)</strong> e <strong>Panels (Painéis)</strong> são elementos fundamentais da interface do Blender. Elas organizam ferramentas, propriedades e configurações de forma estruturada, permitindo acessar grandes quantidades de opções sem sobrecarregar a tela.</p><p>Enquanto as <strong>Tabs</strong> dividem conteúdos em categorias, os <strong>Panels</strong> agrupam configurações relacionadas dentro dessas categorias.</p><hr><h1 id="tabs-abas" tabindex="-1">Tabs (Abas) <a class="header-anchor" href="#tabs-abas" aria-label="Permalink to “Tabs (Abas)”">​</a></h1><p>As Tabs são utilizadas para alternar entre diferentes conjuntos de informações dentro de uma mesma região da interface.</p><p>Somente uma aba pode estar visível por vez.</p><hr><h2 id="funcao-das-tabs" tabindex="-1">Função das Tabs <a class="header-anchor" href="#funcao-das-tabs" aria-label="Permalink to “Função das Tabs”">​</a></h2><p>As abas servem para organizar conteúdos que ocupam o mesmo espaço.</p><h3 id="exemplo-no-editor-de-propriedades" tabindex="-1">Exemplo no Editor de Propriedades <a class="header-anchor" href="#exemplo-no-editor-de-propriedades" aria-label="Permalink to “Exemplo no Editor de Propriedades”">​</a></h3><ul><li>Render Properties</li><li>Output Properties</li><li>View Layer Properties</li><li>Scene Properties</li><li>World Properties</li><li>Object Properties</li><li>Material Properties</li></ul><p>Cada uma possui configurações específicas e aparece apenas quando selecionada.</p><hr><h1 id="tipos-de-cabecalho-de-tabs" tabindex="-1">Tipos de Cabeçalho de Tabs <a class="header-anchor" href="#tipos-de-cabecalho-de-tabs" aria-label="Permalink to “Tipos de Cabeçalho de Tabs”">​</a></h1><h2 id="horizontal" tabindex="-1">Horizontal <a class="header-anchor" href="#horizontal" aria-label="Permalink to “Horizontal”">​</a></h2><p>Encontrado principalmente na Topbar e em algumas áreas da interface.</p><h3 id="exemplo-29" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-29" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ Layout ] [ Modeling ] [ Sculpting ] [ Animation ]</span></span></code></pre></div><hr><h2 id="vertical" tabindex="-1">Vertical <a class="header-anchor" href="#vertical" aria-label="Permalink to “Vertical”">​</a></h2><p>Muito comum no Editor de Propriedades.</p><h3 id="exemplo-30" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-30" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Modeling</span></span>
<span class="line"><span>Animation</span></span>
<span class="line"><span>Render</span></span>
<span class="line"><span>Compositing</span></span>
<span class="line"><span>UV Editing</span></span></code></pre></div><p>Cada item representa uma categoria diferente de propriedades.</p><hr><h1 id="alternando-entre-tabs" tabindex="-1">Alternando Entre Tabs <a class="header-anchor" href="#alternando-entre-tabs" aria-label="Permalink to “Alternando Entre Tabs”">​</a></h1><p>O Blender oferece diversos métodos para trocar de aba.</p><hr><h2 id="ctrl-roda-do-mouse" tabindex="-1">Ctrl + Roda do Mouse <a class="header-anchor" href="#ctrl-roda-do-mouse" aria-label="Permalink to “Ctrl + Roda do Mouse”">​</a></h2><p>Permite alternar entre abas verticais.</p><p>Funciona quando o cursor está sobre a área das abas.</p><hr><h2 id="ctrl-tab" tabindex="-1">Ctrl + Tab <a class="header-anchor" href="#ctrl-tab" aria-label="Permalink to “Ctrl + Tab”">​</a></h2><p>Avança para a próxima aba.</p><hr><h2 id="ctrl-shift-tab" tabindex="-1">Ctrl + Shift + Tab <a class="header-anchor" href="#ctrl-shift-tab" aria-label="Permalink to “Ctrl + Shift + Tab”">​</a></h2><p>Retorna para a aba anterior.</p><hr><h2 id="arrastar-com-o-mouse" tabindex="-1">Arrastar com o Mouse <a class="header-anchor" href="#arrastar-com-o-mouse" aria-label="Permalink to “Arrastar com o Mouse”">​</a></h2><p>Mantendo o botão esquerdo pressionado sobre os ícones das abas, é possível deslizar rapidamente entre elas.</p><hr><h2 id="numpad" tabindex="-1">Numpad . <a class="header-anchor" href="#numpad" aria-label="Permalink to “Numpad .”">​</a></h2><p>Leva a visualização até a aba ativa quando ela estiver fora da área visível.</p><hr><h2 id="observacao-1" tabindex="-1">Observação <a class="header-anchor" href="#observacao-1" aria-label="Permalink to “Observação”">​</a></h2><p>Esses atalhos não funcionam para as abas dos <strong>Workspaces</strong>.</p><p>Os Workspaces possuem controles próprios.</p><hr><h1 id="panels-paineis" tabindex="-1">Panels (Painéis) <a class="header-anchor" href="#panels-paineis" aria-label="Permalink to “Panels (Painéis)”">​</a></h1><p>Os Panels são a menor unidade organizacional da interface do Blender.</p><p>Eles agrupam propriedades relacionadas em blocos organizados.</p><hr><h1 id="estrutura-de-um-painel" tabindex="-1">Estrutura de um Painel <a class="header-anchor" href="#estrutura-de-um-painel" aria-label="Permalink to “Estrutura de um Painel”">​</a></h1><p>Cada painel possui:</p><ul><li>Cabeçalho</li><li>Título</li><li>Conteúdo interno</li></ul><p>Alguns painéis também possuem:</p><ul><li>Subpainéis</li><li>Menus</li><li>Botões</li><li>Campos de configuração</li></ul><hr><h1 id="subpaineis" tabindex="-1">Subpainéis <a class="header-anchor" href="#subpaineis" aria-label="Permalink to “Subpainéis”">​</a></h1><p>Um painel pode conter outros painéis menores.</p><p>Esses são chamados de <strong>Subpanels</strong>.</p><h3 id="exemplo-31" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-31" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Transform</span></span>
<span class="line"><span> ├── Location</span></span>
<span class="line"><span> ├── Rotation</span></span>
<span class="line"><span> └── Scale</span></span></code></pre></div><p>Isso melhora a organização de configurações complexas.</p><hr><h1 id="expandir-e-recolher-paineis" tabindex="-1">Expandir e Recolher Painéis <a class="header-anchor" href="#expandir-e-recolher-paineis" aria-label="Permalink to “Expandir e Recolher Painéis”">​</a></h1><p>Os painéis podem ser abertos ou fechados.</p><hr><h2 id="painel-expandido" tabindex="-1">Painel Expandido <a class="header-anchor" href="#painel-expandido" aria-label="Permalink to “Painel Expandido”">​</a></h2><p>Identificado por:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>▼</span></span></code></pre></div><p>Mostra todo o conteúdo.</p><hr><h2 id="painel-recolhido" tabindex="-1">Painel Recolhido <a class="header-anchor" href="#painel-recolhido" aria-label="Permalink to “Painel Recolhido”">​</a></h2><p>Identificado por:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>►</span></span></code></pre></div><p>Mostra apenas o cabeçalho.</p><hr><h2 id="clique-simples" tabindex="-1">Clique Simples <a class="header-anchor" href="#clique-simples" aria-label="Permalink to “Clique Simples”">​</a></h2><p>Clique no cabeçalho para:</p><ul><li>Expandir</li><li>Recolher</li></ul><p>o painel.</p><hr><h2 id="tecla-a" tabindex="-1">Tecla A <a class="header-anchor" href="#tecla-a" aria-label="Permalink to “Tecla A”">​</a></h2><p>Quando o cursor está sobre um painel:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A</span></span></code></pre></div><p>Expande ou recolhe o painel.</p><hr><h2 id="ctrl-clique-em-painel-fechado" tabindex="-1">Ctrl + Clique em Painel Fechado <a class="header-anchor" href="#ctrl-clique-em-painel-fechado" aria-label="Permalink to “Ctrl + Clique em Painel Fechado”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + LMB</span></span></code></pre></div><p>Expande o painel selecionado e fecha todos os demais.</p><p>Muito útil em regiões com muitos painéis.</p><hr><h2 id="ctrl-clique-em-painel-aberto" tabindex="-1">Ctrl + Clique em Painel Aberto <a class="header-anchor" href="#ctrl-clique-em-painel-aberto" aria-label="Permalink to “Ctrl + Clique em Painel Aberto”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ctrl + LMB</span></span></code></pre></div><p>Expande ou recolhe todos os seus subpainéis.</p><hr><h2 id="arrastar-sobre-cabecalhos" tabindex="-1">Arrastar Sobre Cabeçalhos <a class="header-anchor" href="#arrastar-sobre-cabecalhos" aria-label="Permalink to “Arrastar Sobre Cabeçalhos”">​</a></h2><p>Arrastando o mouse sobre vários cabeçalhos enquanto mantém o botão pressionado, é possível abrir ou fechar vários painéis simultaneamente.</p><hr><h1 id="reorganizacao-de-paineis" tabindex="-1">Reorganização de Painéis <a class="header-anchor" href="#reorganizacao-de-paineis" aria-label="Permalink to “Reorganização de Painéis”">​</a></h1><p>Os painéis podem mudar de posição dentro da região.</p><hr><h2 id="como-mover" tabindex="-1">Como mover <a class="header-anchor" href="#como-mover" aria-label="Permalink to “Como mover”">​</a></h2><p>Utilize o manipulador:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:::</span></span></code></pre></div><p>localizado à direita do cabeçalho.</p><p>Clique e arraste para reposicionar.</p><hr><h2 id="vantagens-1" tabindex="-1">Vantagens <a class="header-anchor" href="#vantagens-1" aria-label="Permalink to “Vantagens”">​</a></h2><p>Permite organizar os painéis mais utilizados em locais de fácil acesso.</p><hr><h1 id="paineis-fixados-pinning" tabindex="-1">Painéis Fixados (Pinning) <a class="header-anchor" href="#paineis-fixados-pinning" aria-label="Permalink to “Painéis Fixados (Pinning)”">​</a></h1><p>Algumas regiões permitem manter um painel visível independentemente da aba selecionada.</p><p>Esse recurso é chamado de <strong>Pinning</strong>.</p><hr><h2 id="funcionamento" tabindex="-1">Funcionamento <a class="header-anchor" href="#funcionamento" aria-label="Permalink to “Funcionamento”">​</a></h2><p>Um painel fixado permanece aberto mesmo quando o usuário troca de aba.</p><h3 id="exemplo-32" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-32" aria-label="Permalink to “Exemplo”">​</a></h3><p>Um usuário pode:</p><ol><li>Fixar propriedades da câmera.</li><li>Selecionar outros objetos.</li><li>Continuar visualizando as configurações da câmera.</li></ol><hr><h1 id="como-fixar" tabindex="-1">Como Fixar <a class="header-anchor" href="#como-fixar" aria-label="Permalink to “Como Fixar”">​</a></h1><h2 id="metodo-1" tabindex="-1">Método 1 <a class="header-anchor" href="#metodo-1" aria-label="Permalink to “Método 1”">​</a></h2><p>Clique no ícone de alfinete presente no cabeçalho.</p><hr><h2 id="metodo-2" tabindex="-1">Método 2 <a class="header-anchor" href="#metodo-2" aria-label="Permalink to “Método 2”">​</a></h2><p>Botão direito no cabeçalho:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pin</span></span></code></pre></div><hr><h2 id="metodo-3" tabindex="-1">Método 3 <a class="header-anchor" href="#metodo-3" aria-label="Permalink to “Método 3”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Shift + LMB</span></span></code></pre></div><p>sobre o painel.</p><hr><h2 id="limitacao" tabindex="-1">Limitação <a class="header-anchor" href="#limitacao" aria-label="Permalink to “Limitação”">​</a></h2><p>Nem todos os painéis suportam fixação.</p><h3 id="exemplos-7" tabindex="-1">Exemplos <a class="header-anchor" href="#exemplos-7" aria-label="Permalink to “Exemplos”">​</a></h3><p><strong>Disponível</strong></p><ul><li>Sidebar</li></ul><p><strong>Não disponível</strong></p><ul><li>Properties Editor</li></ul><hr><h1 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to “Presets”">​</a></h1><p>Diversos painéis possuem um sistema de <strong>Presets</strong>.</p><p>Os presets permitem salvar configurações para reutilização futura.</p><hr><h2 id="o-que-sao-presets" tabindex="-1">O que são Presets? <a class="header-anchor" href="#o-que-sao-presets" aria-label="Permalink to “O que são Presets?”">​</a></h2><p>São conjuntos de valores armazenados pelo Blender.</p><p>Permitem aplicar configurações com apenas um clique.</p><hr><h2 id="exemplo-de-uso" tabindex="-1">Exemplo de Uso <a class="header-anchor" href="#exemplo-de-uso" aria-label="Permalink to “Exemplo de Uso”">​</a></h2><p>Um artista pode criar presets para:</p><ul><li>Iluminação</li><li>Renderização</li><li>Pincéis</li><li>Simulações</li><li>Materiais</li></ul><hr><h1 id="componentes-do-menu-presets" tabindex="-1">Componentes do Menu Presets <a class="header-anchor" href="#componentes-do-menu-presets" aria-label="Permalink to “Componentes do Menu Presets”">​</a></h1><h2 id="lista-de-presets" tabindex="-1">Lista de Presets <a class="header-anchor" href="#lista-de-presets" aria-label="Permalink to “Lista de Presets”">​</a></h2><p>Exibe todos os presets disponíveis.</p><p>Ao selecionar um:</p><ul><li>As configurações são carregadas automaticamente.</li></ul><hr><h2 id="nome-do-preset" tabindex="-1">Nome do Preset <a class="header-anchor" href="#nome-do-preset" aria-label="Permalink to “Nome do Preset”">​</a></h2><p>Campo utilizado para definir o nome de um novo preset.</p><h3 id="exemplo-33" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo-33" aria-label="Permalink to “Exemplo”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Render_Alta_Qualidade</span></span></code></pre></div><hr><h2 id="adicionar" tabindex="-1">Adicionar (+) <a class="header-anchor" href="#adicionar" aria-label="Permalink to “Adicionar (+)”">​</a></h2><p>Cria um novo preset utilizando as configurações atuais.</p><p>O preset passa a ficar disponível na lista.</p><hr><h2 id="remover" tabindex="-1">Remover (-) <a class="header-anchor" href="#remover" aria-label="Permalink to “Remover (-)”">​</a></h2><p>Exclui o preset selecionado.</p><hr><h1 id="armazenamento-dos-presets" tabindex="-1">Armazenamento dos Presets <a class="header-anchor" href="#armazenamento-dos-presets" aria-label="Permalink to “Armazenamento dos Presets”">​</a></h1><p>Os presets são salvos como arquivos Python.</p><h3 id="localizacao" tabindex="-1">Localização <a class="header-anchor" href="#localizacao" aria-label="Permalink to “Localização”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Configuração do Blender</span></span>
<span class="line"><span> └── Presets</span></span></code></pre></div><hr><h1 id="vantagens-dos-presets" tabindex="-1">Vantagens dos Presets <a class="header-anchor" href="#vantagens-dos-presets" aria-label="Permalink to “Vantagens dos Presets”">​</a></h1><p>Usuários avançados podem:</p><ul><li>Editar presets manualmente.</li><li>Compartilhar presets.</li><li>Copiar presets entre computadores.</li><li>Criar bibliotecas personalizadas.</li></ul><p>Isso permite padronizar fluxos de trabalho e reutilizar configurações em diferentes projetos.</p><h2 id="recursos-essenciais" tabindex="-1">Recursos essenciais <a class="header-anchor" href="#recursos-essenciais" aria-label="Permalink to “Recursos essenciais”">​</a></h2><ul><li><a href="https://docs.blender.org/manual/en/latest/" target="_blank" rel="noreferrer">Blender Manual</a></li><li><a href="https://blender.stackexchange.com/" target="_blank" rel="noreferrer">Blender Stack Exchange</a></li><li><a href="https://blenderartists.org/" target="_blank" rel="noreferrer">Blender Artists</a></li><li><a href="https://www.youtube.com/@BlenderGuru" target="_blank" rel="noreferrer">YouTube: Blender Guru</a></li><li><a href="https://www.youtube.com/@cgcookie" target="_blank" rel="noreferrer">YouTube: CG Cookie</a></li></ul>`,960)]))}});export{s as __pageData,c as default};